```javascript
function draw_fw_trend_chart(base_v3, exploit_v3, impact_v3, labels) {
    // ============================================================== 
    // Main Firmware Trends Line Chart
    // ============================================================== 
    var chart = new Chartist.Bar('.firmware_trends', {
        labels: labels,
        series: [
            impact_v3,
            exploit_v3,
            base_v3,
        ]
    }, {
        showArea: true,
        fullWidth: true,
        seriesBarDistance: 25,
        stackBars: false,
        plugins: [
            Chartist.plugins.tooltip()
        ],
        axisX: {
            position: 'start',
            showLabel: true,
            offset: 25,
        },
        axisY: {
            position: 'end',
            showLabel: true,
            onlyInteger: true,
            scaleMinSpace: 15,
            offset: 25,
        },
    });

    // Offset x1 a tiny amount so that the straight stroke gets a bounding box
    // Straight lines don't get a bounding box 
    // Last remark on -> http://www.w3.org/TR/SVG11/coords.html#ObjectBoundingBox
    chart.on('draw', function(ctx) {
        if (ctx.type === 'area') {
            ctx.element.attr({
                x1: ctx.x1 + 0.001
            });
        }
    });

    // Create the gradient definition on created event (always after chart re-render)
    chart.on('created', function(ctx) {
        var defs = ctx.svg.elem('defs');
        defs.elem('linearGradient', {
            id: 'gradient',
            x1: 0,
            y1: 1,
            x2: 0,
            y2: 0
        }).elem('stop', {
            offset: 0,
            'stop-color': 'rgba(255, 255, 255, 1)'
        }).parent().elem('stop', {
            offset: 1,
            'stop-color': 'rgba(64, 196, 255, 1)'
        });
    });

    return chart;
}

// Example usage:
