int main() {
    double matrix[MAX_SIZE][MAX_SIZE];
    int n;

    printf("Enter the size of the matrix (at least 3): ");
    scanf("%d", &n);

    if (n < 3) {
        printf("Matrix size should be at least 3.\n");
        return 1;
    }

    inputMatrix(matrix, n);

    if (isSymmetric(matrix, n)) {
        printf("The matrix is symmetric.\n");

        double eigenvalue;
        double eigenvector[MAX_SIZE];

        powerMethod(matrix, n, &eigenvalue, eigenvector);

        printf("Dominant eigenvalue: %.6f\n", eigenvalue);
        printf("Corresponding eigenvector:\n");
