}

void inputMatrix(double matrix[MAX_SIZE][MAX_SIZE], int n) {
    printf("Enter the matrix elements:\n");
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            scanf("%lf", &matrix[i][j]);
        }
    }
}

int isSymmetric(double matrix[MAX_SIZE][MAX_SIZE], int n) {
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            if (fabs(matrix[i][j] - matrix[j][i]) > EPSILON) {
                return 0;
            }
        }
    }
    return 1;
}

void powerMethod(double matrix[MAX_SIZE][MAX_SIZE], int n, double *eigenvalue, double eigenvector[MAX_SIZE]) {
    double temp[MAX_SIZE];
    double norm;

    // Initialize eigenvector
    for (int i = 0; i < n; i++) {
        eigenvector[i] = 1.0 / sqrt(n);
    }

    for (int iter = 0; iter < 100; iter++) {
        // Matrix-vector multiplication
        for (int i = 0; i < n; i++) {
            temp[i] = 0;
            for (int j = 0; j < n; j++) {
                temp[i] += matrix[i][j] * eigenvector[j];
            }
        }

        // Calculate norm
        norm = 0;
        for (int i = 0; i < n; i++) {
            norm += temp[i] * temp[i];
        }
        norm = sqrt(norm);

        // Update eigenvector
        for (int i = 0; i < n; i++) {
            eigenvector[i] = temp[i] / norm;
        }
    }

    // Calculate eigenvalue
    *eigenvalue = 0;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            *eigenvalue += eigenvector[i] * matrix[i][j] * eigenvector[j];
        }
    }
}
