以下是用C++编写的动态规划法解决0-1背包问题的代码示例：

```cpp
#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

// 0-1 背包问题的动态规划解决方案
int knapsack(int W, const vector<int>& weights, const vector<int>& values) {
    int n = weights.size();
    // 创建一个二维数组 dp，其中 dp[i][w] 表示前 i 个物品在总重量不超过 w 的情况下可以获得的最大价值
    vector<vector<int>> dp(n + 1, vector<int>(W + 1, 0));

    // 填充 dp 数组
    for (int i = 1; i <= n; ++i) {
        for (int w = 0; w <= W; ++w) {
            if (weights[i - 1] <= w) {
