```java
package com.example.broadcastdemo;

import android.content.Intent;
import android.os.Bundle;
import android.view.View;
import android.widget.Button;
import android.widget.EditText;

import androidx.appcompat.app.AppCompatActivity;
import androidx.localbroadcastmanager.content.LocalBroadcastManager;

public class MainActivity extends AppCompatActivity {

    private EditText editTextMessage;
    private Button buttonSend;
    private Button buttonOpenSecond;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);

        editTextMessage = findViewById(R.id.editTextMessage);
        buttonSend = findViewById(R.id.buttonSend);
        buttonOpenSecond = findViewById(R.id.buttonOpenSecond);

        buttonSend.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                String message = editTextMessage.getText().toString();
                sendBroadcast(message);
            }
        });

        buttonOpenSecond.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                Intent intent = new Intent(MainActivity.this, SecondActivity.class);
                startActivity(intent);
            }
        });
    }

    private void sendBroadcast(String message) {
        Intent intent = new Intent("com.example.CUSTOM_ACTION");
        intent.putExtra("message", message);
        LocalBroadcastManager.getInstance(this).sendBroadcast(intent);
    }
}
```

5. 创建`SecondActivity.java`:

```java
package com.example.broadcastdemo;

import android.content.BroadcastReceiver;
import android.content.Context;
import android.content.Intent;
import android.content.IntentFilter;
import android.os.Bundle;
import android.widget.TextView;

import androidx.appcompat.app.AppCompatActivity;
import androidx.localbroadcastmanager.content.LocalBroadcastManager;

public class SecondActivity extends AppCompatActivity {

    private TextView textViewReceived;
    private BroadcastReceiver receiver;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_second);

        textViewReceived = findViewById(R.id.textViewReceived);

        receiver = new BroadcastReceiver() {
            @Override
            public void onReceive(Context context, Intent intent) {
                String message = intent.getStringExtra("message");
                textViewReceived.setText("Received: " + message);
            }
        };
    }

    @Override
    protected void onResume() {
        super.onResume();
        IntentFilter filter = new IntentFilter("com.example.CUSTOM_ACTION");
        LocalBroadcastManager.getInstance(this).registerReceiver(receiver, filter);
    }

    @Override
    protected void onPause() {
        super.onPause();
        LocalBroadcastManager.getInstance(this).unregisterReceiver(receiver);
    }
}
```

这个例子实现了以下功能:

1. MainActivity 有一个输入框和两个按钮。
2. 用户可以在输入框中输入消息,然后点击"Send Broadcast"按钮发送本地广播。
3. 用户可以点击"Open Second Activity"按钮打开第二个Activity。
4. SecondActivity 注册了一个本地广播接收器,可以接收来自MainActivity的广播消息。
5. 当SecondActivity接收到广播时,会在界面上显示接收到的消息。

注意,这个例子使用了LocalBroadcastManager来发送和接收本地广播,这样可以确保广播只在应用内部传递,提高了安全性和效率。

