                {
                    if (distances[i, k] + distances[k, j] < distances[i, j])
                    {
                        distances[i, j] = distances[i, k] + distances[k, j];
                        nextNode[i, j] = nextNode[i, k];
                    }
                }
            }
        }
    }

    public List<Vector3Int> GetPath(Player from, Player to)
    {
        if (from.team == to.team)
        {
            Debug.LogWarning("Trying to find path between players of the same team.");
            return null;
        }

        Vector3Int fromPos = tilemap.WorldToCell(from.transform.position);
        Vector3Int toPos = tilemap.WorldToCell(to.transform.position);

        int fromIndex = System.Array.IndexOf(nodePositions, fromPos);
        int toIndex = System.Array.IndexOf(nodePositions, toPos);

        if (fromIndex == -1 || toIndex == -1)
        {
            Debug.LogError("Player position not found in the pathfinding grid.");
            return null;
        }

        List<Vector3Int> path = new List<Vector3Int>();
        path.Add(fromPos);

        while (fromIndex != toIndex)
        {
            fromIndex = nextNode[fromIndex, toIndex];
            if (fromIndex == -1)
            {
                Debug.LogWarning("No path found between players.");
                return null;
            }
            path.Add(nodePositions[fromIndex]);
        }

        return path;
    }

    public List<Player> GetEnemiesInRange(Player player, int maxDistance)
    {
        List<Player> enemiesInRange = new List<Player>();
        Vector3Int playerPos = tilemap.WorldToCell(player.transform.position);
        int playerIndex = System.Array.IndexOf(nodePositions, playerPos);

        if (playerIndex == -1)
        {
            Debug.LogError("Player position not found in the pathfinding grid.");
            return enemiesInRange;
        }

        foreach (Player otherPlayer in allPlayers)
        {
            if (otherPlayer.team != player.team)
            {
                Vector3Int enemyPos = tilemap.WorldToCell(otherPlayer.transform.position);
                int enemyIndex = System.Array.IndexOf(nodePositions, enemyPos);

                if (enemyIndex != -1 && distances[playerIndex, enemyIndex] <= maxDistance)
                {
                    enemiesInRange.Add(otherPlayer);
                }
            }
        }

        return enemiesInRange;
    }
}
```

