#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/stat.h>

#define FIFO_NAME "myfifo"
#define BUFFER_SIZE 1024

int main() {
    int fd_fifo, fd_write;
    char buffer[BUFFER_SIZE];
    ssize_t bytes_read;

    // 打开有名管道以读取
    fd_fifo = open(FIFO_NAME, O_RDONLY);
    if (fd_fifo == -1) {
        perror("Error opening FIFO for reading");
        exit(1);
    }

    // 打开（或创建）write_text 文件
    fd_write = open("write_text", O_WRONLY | O_CREAT | O_TRUNC, 0666);
    if (fd_write == -1) {
        perror("Error opening write_text");
        exit(1);
    }

    // 从管道读取数据并写入文件
    while ((bytes_read = read(fd_fifo, buffer, BUFFER_SIZE)) > 0) {
        if (write(fd_write, buffer, bytes_read) == -1) {
            perror("Error writing to write_text");
            exit(1);
        }
    }

    // 关闭文件和管道
    close(fd_fifo);
    close(fd_write);

    // 删除有名管道
    unlink(FIFO_NAME);

    return 0;
}
