import numpy as np
from collections import defaultdict
import math

def read_fasta(filename):
    with open(filename, 'r') as file:
        return ''.join(line.strip() for line in file if not line.startswith('>'))

def read_islands(filename):
    islands = []
    with open(filename, 'r') as file:
        for line in file:
            start, end = map(int, line.strip().split())
            islands.append((start, end))
    return islands

def compute_dinucleotide_frequencies(sequence, intervals):
    dinucleotide_counts = defaultdict(int)
    total_dinucleotides = 0

    for start, end in intervals:
        for i in range(start, end - 1):
            dinucleotide = sequence[i:i+2]
            dinucleotide_counts[dinucleotide] += 1
            total_dinucleotides += 1

    frequencies = {k: v / total_dinucleotides for k, v in dinucleotide_counts.items()}
    return frequencies

def build_markov_model(frequencies):
    model = defaultdict(lambda: defaultdict(float))
    for dinucleotide, freq in frequencies.items():
        model[dinucleotide[0]][dinucleotide[1]] = freq
    return model

def compute_cpg_potential(sequence, start, end, cpg_model, non_cpg_model):
    log_prob_cpg = 0
    log_prob_non_cpg = 0

    for i in range(start, end - 1):
        dinucleotide = sequence[i:i+2]
        if dinucleotide[1] in cpg_model[dinucleotide[0]]:
            log_prob_cpg += math.log(cpg_model[dinucleotide[0]][dinucleotide[1]])
        if dinucleotide[1] in non_cpg_model[dinucleotide[0]]:
            log_prob_non_cpg += math.log(non_cpg_model[dinucleotide[0]][dinucleotide[1]])

    return log_prob_cpg - log_prob_non_cpg

def predict_cpg_islands(sequence, cpg_model, non_cpg_model, threshold=0):
    predictions = []
    start = 0
    in_island = False

