        score = compute_cpg_potential(sequence, i, i + 2, cpg_model, non_cpg_model)
        if score > threshold and not in_island:
            start = i
            in_island = True
        elif score <= threshold and in_island:
            predictions.append((start, i + 1))
            in_island = False

    if in_island:
        predictions.append((start, len(sequence)))

    return predictions

def evaluate_predictions(predictions, true_islands):
    true_positive = 0
    false_positive = 0
    false_negative = 0

    for pred_start, pred_end in predictions:
        overlap = 0
        for true_start, true_end in true_islands:
            if true_start < pred_end and pred_start < true_end:
                overlap = min(pred_end, true_end) - max(pred_start, true_start)
                break

