                                          G * (h[i][j+1] - h[i][j-1]) / (2 * DY));
        }
    }

    for (int i = 1; i < NX-1; i++) {
        for (int j = 1; j < NY-1; j++) {
            h[i][j] = h_new[i][j];
            u[i][j] = u_new[i][j];
            v[i][j] = v_new[i][j];
