```c
#include <stdio.h>
#include <stdlib.h>

#define NX 100      // 网格点数
#define NT 1000     // 时间步数
#define ALPHA 0.01  // 热扩散系数
#define DT 0.01     // 时间步长
#define DX 0.1      // 空间步长

void initialize(double *u, int nx) {
    for (int i = 0; i < nx; i++) {
        u[i] = 0.0;
    }
    u[nx / 2] = 100.0; // 初始条件：中间点温度为100
}

void update(double *u, double *u_new, int nx, double alpha, double dt, double dx) {
    for (int i = 1; i < nx - 1; i++) {
        u_new[i] = u[i] + alpha * dt / (dx * dx) * (u[i + 1] - 2 * u[i] + u[i - 1]);
    }
}

