    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Clock and Calendar</title>
    <style>
        body {
            font-family: Arial, sans-serif;
            display: flex;
            flex-direction: column;
            align-items: center;
            height: 100vh;
            margin: 0;
            background-color: #f0f0f0;
        }
        .clock-container {
            display: flex;
            justify-content: space-around;
            width: 100%;
            margin-bottom: 20px;
        }
        #analog-clock {
            width: 200px;
            height: 200px;
            border: 2px solid black;
            border-radius: 50%;
            position: relative;
        }
        #analog-clock .hand {
            position: absolute;
            bottom: 50%;
            left: 50%;
            transform-origin: 50% 100%;
            background-color: black;
        }
        #analog-clock .hour {
            width: 6px;
            height: 60px;
            margin-left: -3px;
        }
        #analog-clock .minute {
            width: 4px;
            height: 80px;
            margin-left: -2px;
        }
        #analog-clock .second {
            width: 2px;
            height: 90px;
            margin-left: -1px;
            background-color: red;
        }
        #digital-clock {
            font-size: 36px;
            font-weight: bold;
        }
        #calendar {
            width: 300px;
            text-align: center;
        }
        #calendar table {
            width: 100%;
            border-collapse: collapse;
        }
        #calendar th, #calendar td {
            padding: 5px;
            border: 1px solid #ccc;
        }
        #calendar th {
            background-color: #f0f0f0;
        }
    </style>
</head>
<body>
    <div class="clock-container">
        <div id="analog-clock">
            <div class="hand hour"></div>
            <div class="hand minute"></div>
            <div class="hand second"></div>
        </div>
        <div id="digital-clock"></div>
    </div>
    <div id="calendar"></div>

    <script>
        function updateClocks() {
            const now = new Date();
            const hours = now.getHours();
            const minutes = now.getMinutes();
            const seconds = now.getSeconds();

            // Update analog clock
            const hourHand = document.querySelector('.hour');
            const minuteHand = document.querySelector('.minute');
            const secondHand = document.querySelector('.second');

            const hourDeg = (hours % 12 + minutes / 60) * 30;
            const minuteDeg = (minutes + seconds / 60) * 6;
            const secondDeg = seconds * 6;

            hourHand.style.transform = `rotate(${hourDeg}deg)`;
            minuteHand.style.transform = `rotate(${minuteDeg}deg)`;
            secondHand.style.transform = `rotate(${secondDeg}deg)`;

            // Update digital clock
            const digitalClock = document.getElementById('digital-clock');
            digitalClock.textContent = `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}`;
        }

        function updateCalendar() {
            const now = new Date();
            const currentMonth = now.getMonth();
            const currentYear = now.getFullYear();
            const firstDay = new Date(currentYear, currentMonth, 1).getDay();
            const daysInMonth = new Date(currentYear, currentMonth + 1, 0).getDate();

            const monthNames = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
            const dayNames = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];

            let calendarHTML = `
                <h2>${monthNames[currentMonth]} ${currentYear}</h2>
                <table>
                    <tr>
                        ${dayNames.map(day => `<th>${day}</th>`).join('')}
                    </tr>
            `;

            let day = 1;
            for (let i = 0; i < 6; i++) {
                calendarHTML += '<tr>';
                for (let j = 0; j < 7; j++) {
                    if (i === 0 && j < firstDay) {
                        calendarHTML += '<td></td>';
                    } else if (day > daysInMonth) {
                        calendarHTML += '<td></td>';
                    } else {
                        calendarHTML += `<td>${day}</td>`;
                        day++;
                    }
                }
                calendarHTML += '</tr>';
                if (day > daysInMonth) break;
            }

            calendarHTML += '</table>';
            document.getElementById('calendar').innerHTML = calendarHTML;
        }

        setInterval(updateClocks, 1000);
        updateCalendar();
        setInterval(updateCalendar, 3600000); // Update calendar every hour
    </script>
</body>
</html>
```

This HTML document includes:

1. An analog clock with hour, minute, and second hands.
2. A 24-hour format digital clock.
3. A monthly calendar showing the current month and year.

The clocks update every second, and the calendar updates every hour. The layout is responsive and should work well on various screen sizes. You can further customize the styles to match your preferences.

