struct Worker {
    handle: Option<ThreadJoinHandle<()>>,
}

impl Worker {
    fn new(receiver: Arc<Mutex<Receiver<Message>>>) -> Self {
        let handle = thread::spawn(move || loop {
            let message = receiver.lock().unwrap().recv().unwrap();
            match message {
                Message::NewTask(task) => {
                    task();
                }
                Message::Shutdown => {
                    break;
                }
            }
        });

        Worker {
            handle: Some(handle),
        }
    }
}
```

