    while (true) {
        int L, R, C;
        cin >> L >> R >> C;
        if (L == 0 && R == 0 && C == 0) break;

        vector<vector<vector<char>>> dungeon(L, vector<vector<char>>(R, vector<char>(C)));
        Position start, end;
        bool foundStart = false, foundEnd = false;

