import java.util.ArrayList;
import java.util.List;

public class ParkingLot {
    private List<ParkingSpot> parkingSpots;

    public ParkingLot(int numberOfSpots) {
        parkingSpots = new ArrayList<>();
        for (int i = 1; i <= numberOfSpots; i++) {
            parkingSpots.add(new ParkingSpot(i));
        }
    }

    public void addParkingSpot() {
        int newSpotNumber = parkingSpots.size() + 1;
        parkingSpots.add(new ParkingSpot(newSpotNumber));
        System.out.println("Added parking spot number " + newSpotNumber);
    }

    public void removeParkingSpot(int spotNumber) {
        if (spotNumber > 0 && spotNumber <= parkingSpots.size()) {
            parkingSpots.remove(spotNumber - 1);
            System.out.println("Removed parking spot number " + spotNumber);
        } else {
            System.out.println("Invalid parking spot number.");
        }
    }

    public void occupySpot(int spotNumber) {
        if (spotNumber > 0 && spotNumber <= parkingSpots.size()) {
            parkingSpots.get(spotNumber - 1).occupy();
        } else {
            System.out.println("Invalid parking spot number.");
        }
    }

    public void vacateSpot(int spotNumber) {
        if (spotNumber > 0 && spotNumber <= parkingSpots.size()) {
            parkingSpots.get(spotNumber - 1).vacate();
        } else {
            System.out.println("Invalid parking spot number.");
        }
    }

    public void displayAllSpots() {
        for (ParkingSpot spot : parkingSpots) {
