class ViewModel {
    @Published var text: String = ""
}

class ViewController: UIViewController {
    var viewModel = ViewModel()
    private var cancellables = Set<AnyCancellable>()

    @IBOutlet weak var textField: UITextField!

    override func viewDidLoad() {
        super.viewDidLoad()

        // Bind text field to view model
        textField.textPublisher
            .assign(to: \.text, on: viewModel)
            .store(in: &cancellables)

        // Bind view model to text field
        viewModel.$text
            .assign(to: \.text, on: textField)
            .store(in: &cancellables)
    }
}
```

Comparison:
- One-way binding is simpler and has less overhead, making it suitable for scenarios where the view is updated less frequently or does not need to update the model.
- Two-way binding is more complex but provides a more seamless synchronization between the model and the view, making it suitable for interactive applications where user inputs need to be reflected in the model immediately.

In summary, the choice between one-way and two-way binding depends on the specific requirements of the application and the desired level of synchronization between the model and the view.

