```cpp
#include <iostream>
#include <vector>
#include <string>

using namespace std;

// 商品类
class Product {
public:
    int id;
    string name;
    double price;
    int stock;

    Product(int id, string name, double price, int stock) 
        : id(id), name(name), price(price), stock(stock) {}
};

// 用户类
class User {
public:
    int id;
    string name;
    string role; // "admin" or "customer"

    User(int id, string name, string role) 
        : id(id), name(name), role(role) {}
};

// 超市管理系统类
class Supermarket {
private:
    vector<Product> products;
    vector<User> users;

public:
    // 添加商品
    void addProduct(int id, string name, double price, int stock) {
        products.push_back(Product(id, name, price, stock));
    }

    // 显示所有商品
    void displayProducts() {
        for (const auto& product : products) {
            cout << "ID: " << product.id << ", Name: " << product.name 
                 << ", Price: " << product.price << ", Stock: " << product.stock << endl;
        }
    }

    // 添加用户
    void addUser(int id, string name, string role) {
        users.push_back(User(id, name, role));
    }

    // 显示所有用户
    void displayUsers() {
        for (const auto& user : users) {
            cout << "ID: " << user.id << ", Name: " << user.name 
                 << ", Role: " << user.role << endl;
        }
    }

    // 销售商品
    void sellProduct(int productId, int quantity) {
        for (auto& product : products) {
            if (product.id == productId) {
                if (product.stock >= quantity) {
                    product.stock -= quantity;
                    cout << "Sold " << quantity << " of " << product.name << endl;
                } else {
                    cout << "Not enough stock for " << product.name << endl;
                }
                return;
            }
        }
        cout << "Product not found" << endl;
    }
};

int main() {
    Supermarket supermarket;

    // 添加一些商品
    supermarket.addProduct(1, "Apple", 0.5, 100);
    supermarket.addProduct(2, "Banana", 0.3, 150);

    // 添加一些用户
    supermarket.addUser(1, "Alice", "admin");
    supermarket.addUser(2, "Bob", "customer");

    // 显示商品和用户
    cout << "Products:" << endl;
    supermarket.displayProducts();

    cout << "Users:" << endl;
    supermarket.displayUsers();

    // 销售商品
    supermarket.sellProduct(1, 20);

    // 显示商品
    cout << "Products after sale:" << endl;
    supermarket.displayProducts();

    return 0;
}
