#include <stdio.h>
#include <stdlib.h>
#include <conio.h>
#include <windows.h>
#include <time.h>

#define Width 80
#define High 20
#define Mode "■"
#define Head "◎"
#define Body "□"
#define APPLE "◆"
#define UP 72
#define DOWN 80
#define LEFT 75
#define RIGHT 77

struct Snake {
    int x[Width * High];
    int y[Width * High];
    int Len;
} s;

struct apple {
    int x;
    int y;
} app;

void _draw_wall() {
    for (int i = 0; i < Width; i++) {
        printf(Mode);
    }
    printf("\n");
    for (int i = 0; i < High - 2; i++) {
        printf(Mode);
        for (int j = 0; j < Width - 2; j++) {
            printf(" ");
        }
        printf(Mode "\n");
    }
    for (int i = 0; i < Width; i++) {
        printf(Mode);
    }
    printf("\n");
}

void _init_snake() {
    s.Len = 3;
    for (int i = 0; i < s.Len; i++) {
        s.x[i] = 5 - i;
        s.y[i] = 5;
    }
}

void _move_snake(int direction) {
    for (int i = s.Len - 1; i > 0; i--) {
        s.x[i] = s.x[i - 1];
        s.y[i] = s.y[i - 1];
    }
    switch (direction) {
        case UP:
            s.y[0]--;
            break;
        case DOWN:
            s.y[0]++;
            break;
        case LEFT:
            s.x[0]--;
            break;
        case RIGHT:
            s.x[0]++;
            break;
    }
}

void _generate_apple() {
    srand(time(NULL));
    app.x = rand() % (Width - 2) + 1;
    app.y = rand() % (High - 2) + 1;
}

void _draw_snake() {
    COORD c;
    for (int i = 0; i < s.Len; i++) {
        c.X = s.x[i];
        c.Y = s.y[i];
        SetConsoleCursorPosition(GetStdHandle(STD_OUTPUT_HANDLE), c);
        if (i == 0) {
            printf(Head);
        } else {
            printf(Body);
        }
    }
}

void _draw_apple() {
    COORD c;
    c.X = app.x;
    c.Y = app.y;
    SetConsoleCursorPosition(GetStdHandle(STD_OUTPUT_HANDLE), c);
    printf(APPLE);
}

int _check_collision() {
    if (s.x[0] == 0 || s.x[0] == Width - 1 || s.y[0] == 0 || s.y[0] == High - 1) {
        return 1;
    }
    for (int i = 1; i < s.Len; i++) {
        if (s.x[0] == s.x[i] && s.y[0] == s.y[i]) {
            return 1;
        }
    }
    return 0;
}

int _check_apple() {
    if (s.x[0] == app.x && s.y[0] == app.y) {
        s.Len++;
        return 1;
    }
    return 0;
}

int main() {
    system("mode con cols=100 lines=50");
    system("title 贪吃蛇");
    system("color 70");

    _draw_wall();
    _init_snake();
    _generate_apple();

    int direction = RIGHT;
    while (1) {
        if (_kbhit()) {
            int key = _getch();
            if (key == 224) {
                key = _getch();
                if (key == UP || key == DOWN || key == LEFT || key == RIGHT) {
                    direction = key;
                }
            }
        }
        _move_snake(direction);
        if (_check_collision()) {
            break;
        }
        if (_check_apple()) {
            _generate_apple();
        }
        system("cls");
        _draw_wall();
        _draw_snake();
        _draw_apple();
        Sleep(100);
    }

    printf("Game Over!\n");
    return 0;
}
```

这个程序实现了一个简单的贪吃蛇游戏，符合你提供的设计规范和要求。游戏开始时，蛇会自动向右移动，玩家可以使用方向键控制蛇的移动方向。当蛇吃到苹果时，蛇的长度会增加。当蛇撞到墙壁或自身时，游戏结束。

