#define Mode "■"
#define Head "◎"
#define Body "□"
#define APPLE "◆"
#define UP 72    
#define DOWN 80  
#define LEFT 75  
#define RIGHT 77 

struct Snake
{
    int x[Width * High];
    int y[Width * High];
    int Len;
} _xw_s;

struct apple
{
    int x;
    int y;
} _xw_app;

void _xw_initGame();
void _xw_drawWall();
void _xw_initSnake();
void _xw_moveSnake();
void _xw_createApple();
int _xw_hitWall();
int _xw_hitSelf();
void _xw_eatApple();
void _xw_show();

int _xw_direction = RIGHT;
int _xw_score = 0;

int main()
{
    _xw_initGame();
    _xw_drawWall();
    _xw_initSnake();
    _xw_createApple();

    while(1)
    {
        _xw_show();
        if(_kbhit())
        {
            char ch = _getch();
            if(isascii(ch))
            {
                switch(ch)
                {
                    case UP: 
                        if(_xw_direction != DOWN) _xw_direction = UP; break;
                    case DOWN: 
                        if(_xw_direction != UP) _xw_direction = DOWN; break;
                    case LEFT: 
                        if(_xw_direction != RIGHT) _xw_direction = LEFT; break;
                    case RIGHT: 
                        if(_xw_direction != LEFT) _xw_direction = RIGHT; break;
                }
            }
        }

        _xw_moveSnake();

        if(_xw_hitWall() || _xw_hitSelf())
        {
            system("cls");
            printf("Game Over! Your score: %d\n", _xw_score);
            break;
        }

        _xw_eatApple();
        Sleep(100);
    }

    system("pause");
    return 0;
}

void _xw_initGame()
{
    system("mode con cols=100 lines=25");
    system("title 贪吃蛇");
    system("color 70");
}

void _xw_drawWall()
{
    for(int i = 0; i <= High; i++)
    {
        _xw_gotoxy(0, i);
        printf(Mode);
        _xw_gotoxy(Width, i);
        printf(Mode);
    }
    for(int i = 0; i <= Width; i++)
    {
        _xw_gotoxy(i, 0);
        printf(Mode);
        _xw_gotoxy(i, High);
        printf(Mode);
    }
}

void _xw_initSnake()
{
    _xw_s.Len = 3;
    _xw_s.x[0] = Width / 2;
    _xw_s.y[0] = High / 2;
    for(int i = 1; i < _xw_s.Len; i++)
    {
        _xw_s.x[i] = _xw_s.x[i-1] - 1;
        _xw_s.y[i] = _xw_s.y[i-1];
    }
}

void _xw_moveSnake()
{
    for(int i = _xw_s.Len - 1; i > 0; i--)
    {
        _xw_s.x[i] = _xw_s.x[i-1];
        _xw_s.y[i] = _xw_s.y[i-1];
    }
    switch(_xw_direction)
    {
        case UP: _xw_s.y[0]--; break;
        case DOWN: _xw_s.y[0]++; break;
        case LEFT: _xw_s.x[0]--; break;
        case RIGHT: _xw_s.x[0]++; break;
    }
}

void _xw_createApple()
{
    srand(time(NULL));
    _xw_app.x = rand() % (Width - 1) + 1;
    _xw_app.y = rand() % (High - 1) + 1;
}

int _xw_hitWall()
{
    if(_xw_s.x[0] == 0 || _xw_s.x[0] == Width || _xw_s.y[0] == 0 || _xw_s.y[0] == High)
        return 1;
    return 0;
}

int _xw_hitSelf()
{
    for(int i = 1; i < _xw_s.Len; i++)
    {
        if(_xw_s.x[0] == _xw_s.x[i] && _xw_s.y[0] == _xw_s.y[i])
            return 1;
    }
    return 0;
}

void _xw_eatApple()
{
    if(_xw_s.x[0] == _xw_app.x && _xw_s.y[0] == _xw_app.y)
    {
        _xw_s.Len++;
        _xw_score += 10;
        _xw_createApple();
    }
}

void _xw_show()
{
    _xw_gotoxy(_xw_app.x, _xw_app.y);
    printf(APPLE);

    _xw_gotoxy(_xw_s.x[0], _xw_s.y[0]);
    printf(Head);

    for(int i = 1; i < _xw_s.Len; i++)
    {
        _xw_gotoxy(_xw_s.x[i], _xw_s.y[i]);
        printf(Body);
    }

    _xw_gotoxy(0, High + 1);
    printf("Score: %d", _xw_score);

    Sleep(50);

    _xw_gotoxy(_xw_s.x[_xw_s.Len - 1], _xw_s.y[_xw_s.Len - 1]);
    printf(" ");
}

void _xw_gotoxy(int x, int y)
{
    COORD c;
    c.X = x;
    c.Y = y;
    SetConsoleCursorPosition(GetStdHandle(STD_OUTPUT_HANDLE), c);
}
```

