#### 实现 `SmartLifecycle`
```java
import org.springframework.context.SmartLifecycle;
import org.springframework.stereotype.Component;

@Component
public class MySmartLifecycle implements SmartLifecycle {

    private boolean running = false;

    @Override
    public void start() {
        running = true;
        // 启动时的逻辑
    }

