#include <QPushButton>
#include <QWidget>
#include <QVBoxLayout>

class MyNode : public rclcpp::Node {
public:
    MyNode() : Node("qt_ros2_publisher") {
        publisher_ = this->create_publisher<std_msgs::msg::String>("topic", 10);
    }

    void publishMessage() {
        auto message = std_msgs::msg::String();
        message.data = "Hello, ROS2!";
        RCLCPP_INFO(this->get_logger(), "Publishing: '%s'", message.data.c_str());
        publisher_->publish(message);
    }

private:
    rclcpp::Publisher<std_msgs::msg::String>::SharedPtr publisher_;
};

int main(int argc, char *argv[]) {
    // Initialize ROS2
    rclcpp::init(argc, argv);

    // Create a ROS2 node
    auto node = std::make_shared<MyNode>();

    // Initialize Qt application
    QApplication app(argc, argv);

    // Create a simple Qt widget with a button
    QWidget window;
    QVBoxLayout layout(&window);
    QPushButton button("Publish Message");
    layout.addWidget(&button);

    // Connect the button's clicked signal to the ROS2 publish function
    QObject::connect(&button, &QPushButton::clicked, [&node]() {
        node->publishMessage();
    });

    // Show the window
    window.show();

    // Start the Qt event loop
    return app.exec();
}
